def tilt_pose(pos, alpha_deg, closing_sign=1):
    a = np.radians(alpha_deg)
    return rh.pose_from_axes(list(pos), [np.sin(a), 0, -np.cos(a)], [0, closing_sign, 0])
for pos in [(0.486, 0.009, 0.046), (0.486, 0.009, 0.13), (0.486, -0.2345, 0.048), (0.486, -0.165, 0.048), (0.486, -0.2345, 0.13)]:
    out = []
    for al in [15, 20, 25, 30, 35, 40, 45, 50]:
        best = None
        for cs in [1, -1]:
            r = ep.ik(tilt_pose(pos, al, cs), seed=list(q0))
            if r["reachable"]:
